namespace HelpDeskApi.Models;

// Priority enum: Defines the urgency level of a ticket
public enum Priority
{
    Low,
    Medium,
    High,
}

// Status enum: Defines the current lifecycle state of a ticket
public enum Status
{
    Open,
    Progress,
    Resolved
}

// Ticket model: Represents the core data structure for a support ticket stored in memory
public class Ticket
{
    // Unique identifier for the ticket (auto-generated by the service)
    public int Id { get; set; }

    // Short summary title of the issue (required)
    public required string Title { get; set; }

    // Detailed explanation of the issue (required)
    public required string Description { get; set; }

    // Urgency level of the ticket
    public Priority Priority { get; set; }

    // Current progress state of the ticket (defaults to Open)
    public Status Status { get; set; }

    // Foreign key reference linking this ticket to a specific Customer ID (required)
    public required int CustomerId { get; set; }
}